// The synthetic Gerbers (tools/synth/generate.mjs, generated by the `pretest` hook) must be
// complete and self-consistent. Parser tests (milestone 1) loop over the same manifest.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const dir = new URL('../../fixtures/synthetic/', import.meta.url);
const read = (path) => readFileSync(new URL(path, dir));
const manifest = JSON.parse(read('manifest.json'));
const EXPECT = new Set(['ok', 'warning', 'error', 'limit']);
const TYPES = new Set(['gerber', 'drill', 'gbrjob']);
const MAX_BYTES = 32 * 1024 * 1024; // "largest ~30 MB" (AGENTS.md)

test('fixtures are up to date with the generator', () => {
  const script = fileURLToPath(new URL('../../../tools/synth/generate.mjs', import.meta.url));
  const stamp = createHash('sha256').update(readFileSync(script)).digest('hex');
  assert.equal(read('.stamp').toString().trim(), stamp, 'run `node tools/synth/generate.mjs`');
});

test('manifest describes every fixture with a valid expectation', () => {
  assert.equal(manifest.generator, 'tools/synth/generate.mjs');
  assert.ok(manifest.fixtures.length > 100);
  const paths = new Set();
  for (const f of manifest.fixtures) {
    assert.ok(!paths.has(f.path), `duplicate ${f.path}`);
    paths.add(f.path);
    assert.ok(EXPECT.has(f.expect), `${f.path}: expect ${f.expect}`);
    assert.ok(TYPES.has(f.type), `${f.path}: type ${f.type}`);
    assert.ok(f.description && f.category, `${f.path}: description and category`);
    assert.equal(statSync(new URL(f.path, dir)).size, f.bytes, `${f.path}: size`);
    assert.ok(f.bytes <= MAX_BYTES, `${f.path} is ${f.bytes} bytes, over the ~30 MB budget`);
    if (f.errorLine !== undefined) assert.ok(Number.isInteger(f.errorLine) && f.errorLine >= 1, `${f.path}: errorLine`);
  }
  for (const e of EXPECT)
    assert.ok(
      manifest.fixtures.some((f) => f.expect === e),
      `no fixture with expect ${e}`,
    );
});

test('the synthetic board set is complete and its job file lists every board file', () => {
  const board = manifest.fixtures.filter((f) => f.category === 'board').map((f) => f.path.replace('board/', ''));
  const job = JSON.parse(read('board/synthetic-board-job.gbrjob'));
  for (const { Path } of job.FilesAttributes) assert.ok(board.includes(Path), `${Path} missing from board set`);
});
